"""TetGen 1.6 text files as the FEMTIC chain uses them: .node .ele .face .neigh (tetgen's output), .poly
(makeTetraMesh's PLC) and .mtr (makeMtr's or tetgen's size field).

Readers keep the file's own numbering (1-based in the chain) and skip '#' comments, so tetgen's trailing
"# Generated by <argv[0]> <switches>" line is ignored; they also keep that trailer and the line ending, so a
writer can reproduce a tetgen file byte for byte. Writer formats are tetgen 1.6's (libigl e05aca7,
tetgen.cxx outnodes 33493, outelements 33827, outsubfaces 34306, outneighbors 34924, outmetrics 33695),
makeTetraMesh's writePLCsToPolyFile (TriangleList.cpp:6298-6366) and makeMtr's writeMtrFile (main.cpp:480-514).
"""
from dataclasses import dataclass
import io

import numpy as np

from . import _fmt


@dataclass
class NodeFile:
    ids: np.ndarray                  # (N,) int64, as written (1-based in the chain)
    xyz: np.ndarray                  # (N, 3) float64, km
    attrs: np.ndarray                # (N, na) float64
    markers: object = None           # (N,) int64 or None
    newline: bytes = b"\n"
    trailer: bytes = b""             # bytes after the last row (tetgen's '# Generated by ...' line)


@dataclass
class EleFile:
    ids: np.ndarray                  # (M,) int64
    tets: np.ndarray                 # (M, 4) int64, node ids as written
    attrs: np.ndarray                # (M, na) float64 (region attribute in column 0 with -A)
    newline: bytes = b"\n"
    trailer: bytes = b""


@dataclass
class FaceFile:
    ids: np.ndarray                  # (F,) int64
    tri: np.ndarray                  # (F, 3) int64, node ids as written
    markers: object = None           # (F,) int64 or None
    newline: bytes = b"\n"
    trailer: bytes = b""


@dataclass
class NeighFile:
    ids: np.ndarray                  # (M,) int64
    neigh: np.ndarray                # (M, 4) int64, element ids as written, -1 = none
    newline: bytes = b"\n"
    trailer: bytes = b""


def _open(path):
    with open(path, "rb") as fh:
        raw = fh.read()
    nl = _fmt.line_ends(raw)
    i = 0
    while i < nl.size:
        s, e = _fmt.line_span(nl, i)
        ln = raw[s:e].split(b"#", 1)[0].strip()
        if ln:
            newline = b"\r\n" if raw[s:e].endswith(b"\r") else b"\n"
            return raw, nl, [int(t) for t in ln.split()], i + 1, newline
        i += 1
    raise ValueError(f"{path}: no header line")


def _is_data(raw, nl, k):
    a, b = _fmt.line_span(nl, k)
    return bool(raw[a:b].split(b"#", 1)[0].strip())


def _body(raw, nl, first, nrows, path, dtype=np.float64):
    """nrows data rows from line `first` on (comments skipped), and the trailer bytes after the last data row.

    Raises ValueError if the file holds fewer or more data rows than nrows."""
    k = nl.size - 1
    while k >= first and not _is_data(raw, nl, k):
        k -= 1
    trailer = raw[int(nl[k]) + 1:] if k >= 0 else raw
    if nrows == 0:
        if k >= first:
            raise ValueError(f"{path}: header says 0 rows but data follows")
        return np.zeros((0, 0)), trailer
    ndata = k - first + 1
    if ndata != nrows:   # interior comments or blank lines: count the data lines one by one
        ndata = sum(_is_data(raw, nl, j) for j in range(first, k + 1))
    if ndata != nrows:
        raise ValueError(f"{path}: header says {nrows} rows, file holds {ndata}")
    s, e = _fmt.line_span(nl, first)
    if k - first + 1 == nrows:                     # no interior comment lines: chunked, preallocated parse
        ncol = len(raw[s:e].split(b"#", 1)[0].split())
        return _fmt.read_table(raw, nl, first, nrows, ncol, dtype, path, comments="#"), trailer
    t = np.loadtxt(io.BytesIO(raw[s:int(nl[k]) + 1]), dtype=dtype, comments="#", ndmin=2)
    if t.shape[0] != nrows:
        raise ValueError(f"{path}: expected {nrows} rows, got {t.shape[0]}")
    return t, trailer


def _int_cols(t, path, what):
    if t.dtype.kind in "iu":
        return t.astype(np.int64, copy=False)
    r = np.round(t)
    if not np.array_equal(r, t):
        raise ValueError(f"{path}: {what} must be integers")
    return r.astype(np.int64)


def read_node(path):
    raw, nl, h, first, newline = _open(path)
    if len(h) < 4:
        raise ValueError(f"{path}: header needs '<#points> <dim> <#attributes> <boundary marker>'")
    n, dim, na, bm = h[:4]
    if dim != 3:
        raise ValueError(f"{path}: Dimension must be 3 !!")
    t, trailer = _body(raw, nl, first, n, path)
    ncol = 4 + na + (1 if bm else 0)
    if n and t.shape[1] != ncol:
        raise ValueError(f"{path}: rows have {t.shape[1]} columns, header implies {ncol}")
    t = t.reshape(n, ncol)
    return NodeFile(ids=_int_cols(t[:, 0], path, "node ids"), xyz=t[:, 1:4].copy(), attrs=t[:, 4:4 + na].copy(),
                    markers=_int_cols(t[:, 4 + na], path, "node markers") if bm else None,
                    newline=newline, trailer=trailer)


def read_ele(path):
    raw, nl, h, first, newline = _open(path)
    if len(h) < 3:
        raise ValueError(f"{path}: header needs '<#tetrahedra> <nodes per tet> <#attributes>'")
    n, npt, na = h[:3]
    if npt != 4:
        raise ValueError(f"{path}: Nodes number of a tetrahedron must be 4 !!")
    try:                                           # tetgen prints integral attributes as integers (%.17g)
        t, trailer = _body(raw, nl, first, n, path, dtype=np.int64)
    except ValueError:
        t, trailer = _body(raw, nl, first, n, path)
    if n and t.shape[1] != 5 + na:
        raise ValueError(f"{path}: rows have {t.shape[1]} columns, header implies {5 + na}")
    t = t.reshape(n, 5 + na)
    return EleFile(ids=_int_cols(t[:, 0], path, "element ids"), tets=_int_cols(t[:, 1:5], path, "node ids"),
                   attrs=t[:, 5:].astype(np.float64), newline=newline, trailer=trailer)


def read_face(path):
    raw, nl, h, first, newline = _open(path)
    if len(h) < 2:
        raise ValueError(f"{path}: header needs '<#faces> <boundary marker>'")
    n, bm = h[:2]
    t, trailer = _body(raw, nl, first, n, path, dtype=np.int64)
    ncol = 4 + (1 if bm else 0)
    if n and t.shape[1] != ncol:
        raise ValueError(f"{path}: rows have {t.shape[1]} columns, expected {ncol} (tetgen -nn adjacency columns "
                         "are not supported: TetGen2Femtic would misread them)")
    t = t.reshape(n, ncol)
    return FaceFile(ids=_int_cols(t[:, 0], path, "face ids"), tri=_int_cols(t[:, 1:4], path, "node ids"),
                    markers=_int_cols(t[:, 4], path, "face markers") if bm else None,
                    newline=newline, trailer=trailer)


def read_neigh(path):
    raw, nl, h, first, newline = _open(path)
    if len(h) < 2 or h[1] != 4:
        raise ValueError(f"{path}: header must be '<#tetrahedra> 4'")
    n = h[0]
    t, trailer = _body(raw, nl, first, n, path, dtype=np.int64)
    if n and t.shape[1] != 5:
        raise ValueError(f"{path}: rows have {t.shape[1]} columns, expected 5")
    t = t.reshape(n, 5)
    return NeighFile(ids=_int_cols(t[:, 0], path, "element ids"), neigh=_int_cols(t[:, 1:5], path, "neighbours"),
                     newline=newline, trailer=trailer)


def _write_lines(path, header, rows, newline, trailer):
    nlc = newline.decode("ascii")
    with open(path, "wb") as fh:
        fh.write((header + nlc).encode("ascii"))
        fh.write("".join(r + nlc for r in rows).encode("ascii"))
        fh.write(trailer)


def write_node(path, f):
    """tetgen's outnodes: '%ld  %d  %d  %d' then '%4d    %.17g  %.17g  %.17g' [+ '  %.17g'] [+ '    %d']."""
    na = f.attrs.shape[1] if f.attrs.ndim == 2 else 0
    bm = f.markers is not None
    rows = []
    for i, (x, y, z) in enumerate(f.xyz.tolist()):
        r = "%4d    %.17g  %.17g  %.17g" % (int(f.ids[i]), x, y, z)
        for v in (f.attrs[i].tolist() if na else []):
            r += "  %.17g" % v
        if bm:
            r += "    %d" % int(f.markers[i])
        rows.append(r)
    _write_lines(path, "%d  %d  %d  %d" % (len(rows), 3, na, 1 if bm else 0), rows, f.newline, f.trailer)


def write_ele(path, f):
    """tetgen's outelements (linear tets): '%ld  %d  %d' then '%5d   %5d %5d %5d %5d' + '    %.17g' per attribute."""
    na = f.attrs.shape[1] if f.attrs.ndim == 2 else 0
    ids, tets = f.ids.tolist(), f.tets.tolist()
    at = f.attrs.tolist() if na else [[]] * len(ids)
    rows = ["%5d   %5d %5d %5d %5d" % (i, *t) + "".join("    %.17g" % v for v in a)
            for i, t, a in zip(ids, tets, at)]
    _write_lines(path, "%d  %d  %d" % (len(rows), 4, na), rows, f.newline, f.trailer)


def write_face(path, f):
    """tetgen's outsubfaces (no -nn): '%ld  %d' then '%5d   %4d  %4d  %4d' [+ '    %d']."""
    bm = f.markers is not None
    mk = f.markers.tolist() if bm else None
    rows = []
    for i, (a, b, c) in enumerate(f.tri.tolist()):
        r = "%5d   %4d  %4d  %4d" % (int(f.ids[i]), a, b, c)
        if bm:
            r += "    %d" % mk[i]
        rows.append(r)
    _write_lines(path, "%d  %d" % (len(rows), 1 if bm else 0), rows, f.newline, f.trailer)


def write_neigh(path, f):
    """tetgen's outneighbors: '%ld  %d' then '%4d    %4d  %4d  %4d  %4d'."""
    rows = ["%4d    %4d  %4d  %4d  %4d" % (i, *n) for i, n in zip(f.ids.tolist(), f.neigh.tolist())]
    _write_lines(path, "%d  %d" % (len(rows), 4), rows, f.newline, f.trailer)


# ----------------------------------------------------------------------------------------------------- .mtr
def read_mtr(path):
    """A .mtr file: '<#points> <#values per point>' then the values. Reads both makeMtr's layout
    ('%10d%10d' + one '%15.6e' per line) and tetgen's (' %-16.8e' per value). Returns (N, msize) float64."""
    raw, nl, h, first, newline = _open(path)
    if len(h) < 2:
        raise ValueError(f"{path}: header must be '<#points> <#values per point>'")
    n, m = h[:2]
    t, trailer = _body(raw, nl, first, n, path)
    if n and t.shape[1] != m:
        raise ValueError(f"{path}: rows have {t.shape[1]} values, header says {m}")
    return t.reshape(n, m)


def write_mtr(path, values, style="makemtr"):
    """style 'makemtr': '%10d%10d' header, one '%15.6e' per line (makeMtr main.cpp:493-509; values must be one
    per point). style 'tetgen': '%ld  %d' header, ' %-16.8e' per value (tetgen outmetrics)."""
    v = np.asarray(values, dtype=np.float64)
    if v.ndim == 1:
        v = v[:, None]
    n, m = v.shape
    with open(path, "wb") as fh:
        if style == "makemtr":
            if m != 1:
                raise ValueError("makeMtr writes one value per point")
            fh.write(b"%10d%10d\n" % (n, 1))
            fh.write("".join("%15.6e\n" % x for x in v[:, 0].tolist()).encode("ascii"))
        elif style == "tetgen":
            fh.write(b"%d  %d\n" % (n, m))
            fh.write("".join("".join(" %-16.8e" % x for x in r) + "\n" for r in v.tolist()).encode("ascii"))
        else:
            raise ValueError(f"unknown .mtr style {style!r}")


# ----------------------------------------------------------------------------------------------------- .poly
@dataclass
class Facet:
    polygons: list                   # each a list of node ids (as written)
    holes: np.ndarray                # (h, 3) float64
    marker: object = None


@dataclass
class PolyFile:
    node_ids: np.ndarray             # (N,) int64
    xyz: np.ndarray                  # (N, 3) float64, km
    node_attrs: np.ndarray           # (N, na)
    node_markers: object             # (N,) or None
    facets: list                     # list of Facet
    facet_markers: bool
    holes: np.ndarray                # (H, 3)
    region_ids: np.ndarray           # (R,)
    regions: np.ndarray              # (R, 5): x, y, z, attribute, max volume (nan if absent)


def read_poly(path):
    """A tetgen .poly file with its points inline (makeTetraMesh's output.poly, seeded or not)."""
    with open(path, "r", encoding="ascii") as fh:
        lines = [ln.split("#", 1)[0].split() for ln in fh]
    lines = [ln for ln in lines if ln]
    it = iter(lines)

    def nxt(what):
        try:
            return next(it)
        except StopIteration:
            raise ValueError(f"{path}: file ends before {what}") from None
    h = [int(v) for v in nxt("the point header")]
    n, dim, na, bm = (h + [0, 0, 0, 0])[:4]
    if n == 0:
        raise NotImplementedError(f"{path}: points in a separate .node file are not supported")
    if dim != 3:
        raise ValueError(f"{path}: dimension must be 3")
    pts = np.array([[float(v) for v in nxt(f"point {i}")[:4 + na + bm]] for i in range(n)], dtype=np.float64)
    if pts.shape != (n, 4 + na + bm):
        raise ValueError(f"{path}: point rows need {4 + na + bm} values")
    fh_ = [int(v) for v in nxt("the facet header")]
    nf, fbm = fh_[0], (fh_[1] if len(fh_) > 1 else 0)
    facets = []
    for k in range(nf):
        r = [int(v) for v in nxt(f"facet {k + 1}")]
        npoly, nh = r[0], (r[1] if len(r) > 1 else 0)
        mk = r[2] if (fbm and len(r) > 2) else None
        polys = []
        for _ in range(npoly):
            p = [int(v) for v in nxt(f"a polygon of facet {k + 1}")]
            if len(p) != p[0] + 1:
                raise ValueError(f"{path}: polygon of facet {k + 1} lists {len(p) - 1} corners, says {p[0]}")
            polys.append(p[1:])
        hl = np.array([[float(v) for v in nxt(f"a hole of facet {k + 1}")[1:4]] for _ in range(nh)]).reshape(-1, 3)
        facets.append(Facet(polygons=polys, holes=hl, marker=mk))
    nh = int(nxt("the hole count")[0])
    holes = np.array([[float(v) for v in nxt("a hole")[1:4]] for _ in range(nh)]).reshape(-1, 3)
    reg = next(it, None)
    nr = int(reg[0]) if reg else 0
    rid, rr = [], []
    for _ in range(nr):
        r = nxt("a region")
        rid.append(int(r[0]))
        vals = [float(v) for v in r[1:6]]
        rr.append(vals + [float("nan")] * (5 - len(vals)))
    if next(it, None) is not None:
        raise ValueError(f"{path}: unexpected content after the region list")
    return PolyFile(node_ids=_int_cols(pts[:, 0], path, "point ids"), xyz=pts[:, 1:4].copy(),
                    node_attrs=pts[:, 4:4 + na].copy(), node_markers=pts[:, 4 + na].astype(np.int64) if bm else None,
                    facets=facets, facet_markers=bool(fbm), holes=holes,
                    region_ids=np.array(rid, dtype=np.int64), regions=np.array(rr, dtype=np.float64).reshape(-1, 5))


def write_poly(path, p):
    """makeTetraMesh's writePLCsToPolyFile layout for points and facets ('%10d' + '%30.15e' x 3), then holes and
    regions. Regions are written as run_mesh_chain.sh appends them ('%d x y z attr maxvol', '%.17g' numbers)."""
    out = ["%10d%10d%10d%10d" % (len(p.xyz), 3, p.node_attrs.shape[1] if p.node_attrs.ndim == 2 else 0,
                                 1 if p.node_markers is not None else 0), "# Part 1"]
    for i, (x, y, z) in zip(p.node_ids.tolist(), p.xyz.tolist()):
        out.append("%10d%30.15e%30.15e%30.15e" % (i, x, y, z))
    out += ["# Part 2", "%10d%10d" % (len(p.facets), 1 if p.facet_markers else 0)]
    ih = 0
    for k, f in enumerate(p.facets):
        mk = ("%10d" % f.marker) if (p.facet_markers and f.marker is not None) else ""
        out.append("%10d%10d%s #%d" % (len(f.polygons), len(f.holes), mk, k + 1))
        for poly in f.polygons:
            out.append("%10d" % len(poly) + "".join("%10d" % v for v in poly))
        for x, y, z in f.holes.tolist():
            ih += 1
            out.append("%10d%30.15e%30.15e%30.15e" % (ih, x, y, z))
    out += ["# Part 3", "%d" % len(p.holes)]
    out += ["%d %.17g %.17g %.17g" % (i + 1, *h) for i, h in enumerate(p.holes.tolist())]
    out += ["# Part 4", "%d" % len(p.regions)]
    for i, r in zip(p.region_ids.tolist(), p.regions.tolist()):
        vals = [v for v in r if v == v]
        out.append("%d " % i + " ".join(("%d" % v) if j == 3 else ("%.17g" % v) for j, v in enumerate(vals)))
    with open(path, "wb") as fh:
        fh.write(("\n".join(out) + "\n").encode("ascii"))
